{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The closest retrieved analogue, emodin-8-O-β-D-glucoside, was detected in rat brain tissue after systemic administration in a dose-dependent manner, demonstrating that the emodin/chrysophanol anthraquinone scaffold can achieve meaningful CNS access despite the glycoside's added polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Menadione, a methyl-naphthoquinone sharing the methylated quinone motif, passed easily into marmoset brain after systemic injection, supporting CNS permeability for the methylated quinone/anthraquinone core of chrysophanol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "An aza-anthraquinone analogue was detected in mouse cortex, striatum, and CSF after systemic dosing and was classified as passive diffusion, supporting CNS access for the lipophilic anthraquinone-like core shared with chrysophanol.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Orcinol, a small phenolic compound sharing the methyl-phenol substructure, was qualitatively detected in mouse brain by HPLC-MS after systemic administration, supporting that small phenolic/anthraquinone fragments can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ezogabine, a structurally distant small molecule, showed a low brain-to-plasma AUC ratio of 0.16 in mice, providing a contradictory example; however, its low Morgan similarity and different chemotype limit transfer to chrysophanol.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Chrysophanol is a lipophilic, low-molecular-weight anthraquinone. The closest anthraquinone analogue and related methyl-quinones show measurable brain penetration after systemic administration, while the few contradictory examples are structurally distant or explained by unfavorable polarity. Overall evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for chrysophanol itself in the retrieved set; the closest evidence is an emodin glycoside and related quinones.",
    "Efflux transporter status of chrysophanol at the BBB was not directly assessed in the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

